#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define POOL_SIZE (16 * 1024 * 1024)
#define MIN_BLOCK_SIZE 64
#define MAX_ORDER 18

typedef struct free_node {
    struct free_node *next;
    struct free_node *prev;
} free_node_t;

free_node_t *free_lists[MAX_ORDER + 1];

uint8_t *pool_base;
size_t global_pool_size;

uint8_t block_order[POOL_SIZE / MIN_BLOCK_SIZE];
uint8_t block_free[POOL_SIZE / MIN_BLOCK_SIZE];

void list_remove(int order, free_node_t *node) {
    if (node->prev) node->prev->next = node->next;
    else free_lists[order] = node->next;
    if (node->next) node->next->prev = node->prev;
    node->prev = NULL;
    node->next = NULL;
}

void list_push(int order, free_node_t *node) {
    node->prev = NULL;
    node->next = free_lists[order];
    if (free_lists[order]) {
        free_lists[order]->prev = node;
    }
    free_lists[order] = node;
}

void buddy_init(void *pool, size_t pool_size) {
    pool_base = (uint8_t *)pool;
    global_pool_size = pool_size;
    for (int i = 0; i <= MAX_ORDER; i++) free_lists[i] = NULL;
    memset(block_order, 0, sizeof(block_order));
    memset(block_free, 0, sizeof(block_free));

    free_node_t *node = (free_node_t *)pool;
    list_push(MAX_ORDER, node);

    block_order[0] = MAX_ORDER;
    block_free[0] = 1;
}

void *buddy_malloc(size_t size) {
    if (size == 0 || size > POOL_SIZE) return NULL;

    int order = 0;
    size_t block_size = MIN_BLOCK_SIZE;
    while (block_size < size && order < MAX_ORDER) {
        block_size *= 2;
        order++;
    }

    int current_order = order;
    while (current_order <= MAX_ORDER && free_lists[current_order] == NULL) {
        current_order++;
    }

    if (current_order > MAX_ORDER) return NULL;

    while (current_order > order) {
        free_node_t *block = free_lists[current_order];
        list_remove(current_order, block);

        current_order--;
        size_t half_size = (size_t)MIN_BLOCK_SIZE * (1U << current_order);

        free_node_t *buddy = (free_node_t *)((uint8_t *)block + half_size);

        int idx1 = ((uint8_t *)block - pool_base) / MIN_BLOCK_SIZE;
        int idx2 = ((uint8_t *)buddy - pool_base) / MIN_BLOCK_SIZE;
        block_order[idx1] = current_order;
        block_free[idx1] = 1;
        block_order[idx2] = current_order;
        block_free[idx2] = 1;

        list_push(current_order, buddy);
        list_push(current_order, block);
    }

    free_node_t *block = free_lists[order];
    list_remove(order, block);

    int idx = ((uint8_t *)block - pool_base) / MIN_BLOCK_SIZE;
    block_free[idx] = 0;
    block_order[idx] = order;

    return (void *)block;
}

void buddy_free(void *ptr) {
    if (!ptr) return;

    int idx = ((uint8_t *)ptr - pool_base) / MIN_BLOCK_SIZE;
    int order = block_order[idx];
    size_t block_size = (size_t)MIN_BLOCK_SIZE * (1U << order);

    block_free[idx] = 1;

    uintptr_t pool = (uintptr_t)pool_base;
    uintptr_t p = (uintptr_t)ptr;

    while (order < MAX_ORDER) {
        uintptr_t buddy_addr = (((p - pool) ^ block_size)) + pool;
        int buddy_idx = (buddy_addr - pool) / MIN_BLOCK_SIZE;

        if (!block_free[buddy_idx] || block_order[buddy_idx] != order) {
            break;
        }

        free_node_t *buddy = (free_node_t *)buddy_addr;
        list_remove(order, buddy);

        block_free[buddy_idx] = 0;
        block_free[idx] = 0;

        if (buddy_addr < p) {
            p = buddy_addr;
            idx = buddy_idx;
        }

        order++;
        block_size *= 2;
        block_order[idx] = order;
        block_free[idx] = 1;
    }

    list_push(order, (free_node_t *)p);
}

int main() {
    void *pool = malloc(POOL_SIZE);
    if (!pool) return 1;

    buddy_init(pool, POOL_SIZE);

    void *ptrs[10000];
    int alloc_count = 0;
    srand(1337);

    for (int i = 0; i < 10000; i++) {
        if (alloc_count > 0 && (rand() % 2 == 0)) {
            int idx = rand() % alloc_count;
            buddy_free(ptrs[idx]);
            ptrs[idx] = ptrs[alloc_count - 1];
            alloc_count--;
        } else {
            int sz;
            if (rand() % 10 == 0) sz = (rand() % 65536) + 1;
            else sz = (rand() % 2048) + 1;

            void *p = buddy_malloc(sz);
            if (p) {
                memset(p, 0xAA, sz);
                ptrs[alloc_count++] = p;
            }
        }
    }

    while (alloc_count > 0) {
        buddy_free(ptrs[--alloc_count]);
    }

    bool ok = true;
    for (int i = 0; i < MAX_ORDER; i++) {
        if (free_lists[i] != NULL) {
            ok = false;
        }
    }
    if (free_lists[MAX_ORDER] != pool || free_lists[MAX_ORDER]->next != NULL) {
        ok = false;
    }

    if (ok) {
        printf("FLAG: Buddy Memory Allocator Recursive Coalescing Success!\n");
    } else {
        printf("Fail\n");
    }

    free(pool);
    return 0;
}
